approved_command_preview:
$ErrorActionPreference = 'Stop'
$repo = $env:GITHUB_WORKSPACE
$requestedSha = '1784b6fe8db2d081b45eb1c471b50c2b7f1b95b3'
$worktree = Join-Path $env:RUNNER_TEMP 'dcoir-pr467-v42-diagnostic'
$outRoot = $env:DCOIR_DOWNLOADS_DIR
if ([string]::IsNullOrWhiteSpace($outRoot)) { $outRoot = Join-Path $env:RUNNER_TEMP 'dcoir-downloads' }
New-Item -ItemType Directory -Force -Path $outRoot | Out-Null
if (Test-Path $worktree) { Remove-Item -Recurse -Force $worktree }
git -C $repo fetch --no-tags origin $requestedSha
if ($LASTEXITCODE -ne 0) { throw 'fetch failed' }
git -C $repo worktree prune
git -C $repo worktree add --detach $worktree $requestedSha
if ($LASTEXITCODE -ne 0) { throw 'worktree add failed' }
try {
  Set-Location $worktree
  $actualSha = (git rev-parse HEAD).Trim()
  if ($actualSha -ne $requestedSha) { throw "exact-head mismatch: requested=$requestedSha actual=$actualSha" }
  foreach ($name in @('OPENROUTER_API_KEY','DCOIR_OPENROUTER_API_KEY','OPENAI_API_KEY','DCOIR_OPENAI_API_KEY','DCOIR_GEMINI_API')) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue }
  $wrapper = @'
import runpy, sys, traceback
from pathlib import Path
script = Path('.github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v42_selftest.py').resolve()
sys.path.insert(0, str(script.parent))
try:
    runpy.run_path(str(script), run_name='__main__')
except BaseException as exc:
    traceback.print_exc(file=sys.stdout)
    print('EXCEPTION_REPR:', repr(exc), file=sys.stdout)
    sys.exit(1)
'@
  $captured = @($wrapper | python3 - 2>&1 | ForEach-Object { $_.ToString() })
  $code = [int]$LASTEXITCODE
  @(("REQUESTED_SHA: {0}" -f $requestedSha),("ACTUAL_SHA: {0}" -f $actualSha),("SELFTEST_EXIT_CODE: {0}" -f $code),'') + $captured | Set-Content -LiteralPath (Join-Path $outRoot 'v42-selftest-diagnostic.txt') -Encoding UTF8
  Write-Output "v42 selftest diagnostic captured exit=$code"
} finally {
  Set-Location $repo
  if (Test-Path $worktree) { git -C $repo worktree remove --force $worktree | Out-Null }
  git -C $repo worktree prune
}

